import{c as i,Q as a,j as o,g as s,n as r,a3 as n,m as l}from"./chunks/framework.7Akk-szY.js";const q=JSON.parse('{"title":"Revues de code","description":"","frontmatter":{"title":"Revues de code","status":"review","tags":["oo-pratiques","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"oo-pratiques/revues-code.md","filePath":"oo-pratiques/revues-code.md"}'),u={name:"oo-pratiques/revues-code.md"},d={id:"frontmatter-title",tabindex:"-1"};function c(t,e,p,m,h,v){return a(),o("div",null,[s("h1",d,[r(n(t.$frontmatter.title)+" ",1),e[0]||(e[0]=s("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=l('<p>La revue de code est le processus par lequel des développeurs examinent le code des autres pour trouver des problèmes, partager des connaissances et améliorer la qualité collective du code.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Expliquer la valeur des revues de code dans un contexte professionnel</li><li>Donner et recevoir des commentaires de code de façon constructive</li><li>Identifier les aspects à vérifier lors d&#39;une revue de code</li><li>Distinguer les problèmes critiques des suggestions stylistiques</li></ul></div><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Expliquer la valeur des revues de code dans un contexte professionnel</li><li>Donner et recevoir des commentaires de code de façon constructive</li><li>Identifier les aspects à vérifier lors d&#39;une revue de code</li><li>Différencier les problèmes critiques des suggestions stylistiques</li></ul></div><h2 id="pourquoi-les-revues-de-code" tabindex="-1">Pourquoi les revues de code ? <a class="header-anchor" href="#pourquoi-les-revues-de-code" aria-label="Permalink to &quot;Pourquoi les revues de code ?&quot;">​</a></h2><ul><li><strong>Détection d&#39;erreurs</strong> : un deuxième regard voit des problèmes que l&#39;auteur a ratés</li><li><strong>Partage de connaissance</strong> : toute l&#39;équipe comprend le code, pas seulement l&#39;auteur</li><li><strong>Cohérence</strong> : le style et les pratiques sont uniformes dans le projet</li><li><strong>Apprentissage mutuel</strong> : les développeurs apprennent les uns des autres</li></ul><h2 id="ce-qu-on-verifie-dans-une-revue" tabindex="-1">Ce qu&#39;on vérifie dans une revue <a class="header-anchor" href="#ce-qu-on-verifie-dans-une-revue" aria-label="Permalink to &quot;Ce qu&#39;on vérifie dans une revue&quot;">​</a></h2><h3 id="exactitude" tabindex="-1">Exactitude <a class="header-anchor" href="#exactitude" aria-label="Permalink to &quot;Exactitude&quot;">​</a></h3><ul><li>Le code fait-il ce qu&#39;il est censé faire ?</li><li>Les cas limites sont-ils gérés ?</li><li>Les exceptions sont-elles lancées au bon endroit ?</li></ul><h3 id="lisibilite" tabindex="-1">Lisibilité <a class="header-anchor" href="#lisibilite" aria-label="Permalink to &quot;Lisibilité&quot;">​</a></h3><ul><li>Les noms sont-ils expressifs ?</li><li>Les méthodes sont-elles courtes et à responsabilité unique ?</li><li>Y a-t-il de la duplication évitable ?</li></ul><h3 id="conception" tabindex="-1">Conception <a class="header-anchor" href="#conception" aria-label="Permalink to &quot;Conception&quot;">​</a></h3><ul><li>Les responsabilités sont-elles bien réparties (SRP) ?</li><li>Le code respecte-t-il Tell Don&#39;t Ask et la loi de Déméter ?</li><li>Y a-t-il des code smells (God class, méthode trop longue, etc.) ?</li></ul><h3 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h3><ul><li>Les cas limites sont-ils testés ?</li><li>Les noms de tests décrivent-ils bien les comportements ?</li><li>Les tests sont-ils isolés et déterministes ?</li></ul><h2 id="donner-des-commentaires-constructifs" tabindex="-1">Donner des commentaires constructifs <a class="header-anchor" href="#donner-des-commentaires-constructifs" aria-label="Permalink to &quot;Donner des commentaires constructifs&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Commenter le code, pas la personne</p><p>&quot;Cette méthode fait deux choses, on pourrait l&#39;extraire en deux méthodes distinctes.&quot; -pas - &quot;Tu écris du mauvais code.&quot;</p></div><h3 id="ton-neutre-et-precis" tabindex="-1">Ton neutre et précis <a class="header-anchor" href="#ton-neutre-et-precis" aria-label="Permalink to &quot;Ton neutre et précis&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Avant : &quot;C&#39;est illisible.&quot;</span></span>\n<span class="line"><span>Après : &quot;La méthode `traiterDonnees()` est difficile à suivre car elle mélange</span></span>\n<span class="line"><span>         la validation et le calcul. On pourrait extraire une méthode `valider()`.&quot;</span></span></code></pre></div><h3 id="proposer-une-alternative" tabindex="-1">Proposer une alternative <a class="header-anchor" href="#proposer-une-alternative" aria-label="Permalink to &quot;Proposer une alternative&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;Je suggère d&#39;utiliser une énumération ici plutôt que des entiers,</span></span>\n<span class="line"><span> car cela empêche les valeurs invalides au moment de la compilation.&quot;</span></span></code></pre></div><h3 id="distinguer-priorite-et-preference" tabindex="-1">Distinguer priorité et préférence <a class="header-anchor" href="#distinguer-priorite-et-preference" aria-label="Permalink to &quot;Distinguer priorité et préférence&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CRITIQUE : &quot;Cette condition inverse la logique - elle laisse passer les données invalides.&quot;</span></span>\n<span class="line"><span>SUGGESTION : &quot;Je préférerais `estValide()` à `pasInvalide()` pour la lisibilité.&quot;</span></span>\n<span class="line"><span>QUESTION : &quot;Pourquoi utilises-tu un ArrayList ici plutôt qu&#39;un Set ?&quot;</span></span></code></pre></div><h2 id="recevoir-des-commentaires" tabindex="-1">Recevoir des commentaires <a class="header-anchor" href="#recevoir-des-commentaires" aria-label="Permalink to &quot;Recevoir des commentaires&quot;">​</a></h2><ul><li><strong>Écouter</strong> sans se défendre immédiatement</li><li><strong>Poser des questions</strong> pour comprendre le commentaire</li><li><strong>Distinguer</strong> les opinions personnelles des problèmes réels</li><li><strong>Remercier</strong> - la revue de code est un service rendu, pas une attaque</li></ul><div class="warning custom-block"><p class="custom-block-title">Le code n&#39;est pas ton identité</p><p>Un commentaire sur ton code n&#39;est pas un jugement sur toi. Les développeurs expérimentés reçoivent des revues de code tous les jours - c&#39;est une pratique normale, pas un signe de faiblesse.</p></div><h2 id="tribunal-du-code-format-pedagogique" tabindex="-1">Tribunal du Code - format pédagogique <a class="header-anchor" href="#tribunal-du-code-format-pedagogique" aria-label="Permalink to &quot;Tribunal du Code - format pédagogique&quot;">​</a></h2><p>Dans ce cours, le &quot;Tribunal du Code&quot; est un exercice où on examine des extraits de code réels et on débat de leur qualité. Pour chaque cas :</p><ol><li><strong>L&#39;accusation</strong> : quelle règle est potentiellement non-respectée ?</li><li><strong>La défense</strong> : y a-t-il une justification valable ?</li><li><strong>Le verdict</strong> : faut-il corriger ? Comment ?</li></ol><p>Ce format développe le jugement professionnel : reconnaître que les règles sont des guidelines avec des exceptions justifiées, pas des absolus.</p>',30))])}const b=i(u,[["render",c]]);export{q as __pageData,b as default};
